const tetEdges = [[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]];

function cylBetween(p1, p2, radius, color, matType) {
  const dir = new THREE.Vector3().subVectors(p2, p1);
  const len = dir.length();
  if (len < 1e-6) return new THREE.Group();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 10);
  const mat = matType === 'standard'
    ? new THREE.MeshStandardMaterial({ color, roughness: 0.5, metalness: 0.1 })
    : new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(p1).add(p2).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), dir.normalize());
  return mesh;
}

function makeEdgeLines(center, color, skipEdges) {
  const pos = [];
  for (const [i, j] of tetEdges) {
    if (skipEdges && skipEdges.some(([a,b]) => (a===i&&b===j)||(a===j&&b===i))) continue;
    const vi = tetVerts[i], vj = tetVerts[j];
    pos.push(vi.x+center.x, vi.y+center.y, vi.z+center.z);
    pos.push(vj.x+center.x, vj.y+center.y, vj.z+center.z);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  return new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color }));
