// --- Ball-and-stick model (right) ---
const mc = new THREE.Vector3(4.5, 0, 0);
const bsBondLen = 0.72;
// Tetrahedral directions (rotated -30° about Y for visual match)
const bsDirs = [
  new THREE.Vector3(0, 1, 0),
  new THREE.Vector3(0.816, -0.333, 0.471),
  new THREE.Vector3(-0.816, -0.333, 0.471),
  new THREE.Vector3(0, -0.333, -0.943),
];
const bsBondType = ['inPlane', 'inPlane', 'outOfPlane', 'receding'];

const carbonMesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.28, 28, 28),
  new THREE.MeshStandardMaterial({ color: 0x4a4a4a, roughness: 0.4, metalness: 0.15 })
);
carbonMesh.position.copy(mc);
scene.add(carbonMesh);

const hMeshes = [], rodMeshes = [];
for (let i = 0; i < 4; i++) {
  const hp = mc.clone().add(bsDirs[i].clone().multiplyScalar(bsBondLen));
  const hm = new THREE.Mesh(
    new THREE.SphereGeometry(0.17, 22, 22),
    new THREE.MeshStandardMaterial({ color: 0xd9d9c9, roughness: 0.5, metalness: 0.05 })
  );
  hm.position.copy(hp);
  scene.add(hm);
  hMeshes.push(hm);

  const rodStart = mc.clone().add(bsDirs[i].clone().multiplyScalar(0.28));
  const rodEnd = hp.clone().sub(bsDirs[i].clone().multiplyScalar(0.17));
  const rod = cylBetween(rodStart, rodEnd, 0.04, 0xb0b0b0, 'standard');
  scene.add(rod);
  rodMeshes.push(rod);
}

// --- Curly brace ---
{
  const bx1 = -0.8, bx2 = 5.8, by = -1.7, dip = 0.22;
  const pts = [];
  const n = 80;
  const mid = (bx1 + bx2) / 2;
  const halfW = (bx2 - bx1) / 2;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const x = bx1 + t * (bx2 - bx1);
    let dy = 0;
    const dMid = Math.abs(x - mid) / halfW;
    if (dMid < 0.04) dy = -dip;
    else if (dMid < 0.12) {
      const s = (dMid - 0.04) / 0.08;
      dy = -dip * (1 - s) * (1 - s);
    }
    // End curls
    if (t < 0.025) dy += 0.08 * Math.sin(t / 0.025 * Math.PI);
    else if (t > 0.975) dy += 0.08 * Math.sin((1 - t) / 0.025 * Math.PI);
    pts.push(new THREE.Vector3(x, by + dy, 0));
  }
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  scene.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x333333 })));
}

