// --- Highlight system ---
const GOLD = 0xffcc00;
const GOLD_CSS = '#ffcc00';
let currentHighlight = 'None';

function setHighlight(state) {
  currentHighlight = state;
  document.getElementById('highlightSelect').value = state;

  // Reset notation bonds
  for (const cat of ['inPlane', 'receding', 'outOfPlane']) {
    for (const obj of (notationBonds[cat] || [])) {
      if (obj.material) {
        if (obj.material.color) obj.material.color.set(0x111111);
      }
    }
    for (const obj of (leaderGroups[cat] || [])) {
      if (obj.material && obj.material.color) obj.material.color.set(0x333333);
    }
  }
  // Reset rods
  for (const rod of rodMeshes) {
    rod.traverse(o => { if (o.material && o.material.color) o.material.color.set(0xb0b0b0); });
  }

  if (state === 'None') return;

  const catKey = state === 'In plane' ? 'inPlane' : state === 'Receding' ? 'receding' : 'outOfPlane';

  // Highlight notation bonds
  for (const obj of (notationBonds[catKey] || [])) {
    if (obj.material && obj.material.color) obj.material.color.set(GOLD);
  }
  // Highlight leader arrows
  for (const obj of (leaderGroups[catKey] || [])) {
    if (obj.material && obj.material.color) obj.material.color.set(GOLD);
  }
  // Highlight 3D rods
  for (let i = 0; i < 4; i++) {
    if (bsBondType[i] === catKey) {
      rodMeshes[i].traverse(o => { if (o.material && o.material.color) o.material.color.set(GOLD); });
    }
  }
}

// --- UI wiring ---
document.getElementById('highlightSelect').addEventListener('change', (e) => {
